package com.nigson.experience.notification;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.experience.platform.*;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;

class NotificationPersistenceTest {
    private JdbcTemplate jdbc;private NotificationOutcomeService service;private PrivateWorkload.Proof proof;private UUID resource;
    @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"notification PostgreSQL acceptance requires native owner DB");if(!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime");jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();var clock=Clock.systemUTC();var store=new PlatformStore(jdbc,manager,clock,metrics);service=new NotificationOutcomeService(jdbc,store,new AuditWriter(jdbc,clock,metrics),metrics);resource=UUID.randomUUID();jdbc.update("INSERT INTO experience.lead(id,created_by,updated_by,type,name,email,subject,message,status,source) VALUES (?, 'notification-test','notification-test','CONTACT','Synthetic','synthetic@example.invalid','Synthetic notification resource','fixture','NEW','WEB')",resource);var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-137")).findFirst().orElseThrow();proof=new PrivateWorkload.Proof(route.client(),"synthetic-integration",route,null);}
    private NotificationValues.Delivery delivery(UUID job,UUID res,String state){return new NotificationValues.Delivery(job,res,state,"SM0123456789abcdef0123456789abcdef");}
    private NotificationValues.Acknowledged record(UUID job,UUID res,String state,String key){return service.record(proof,delivery(job,res,state),key,UUID.randomUUID());}

    @Test void api137DurablyDeduplicatesJobStateAndOnlyReconcilesUnknownToTerminal(){UUID job=UUID.randomUUID();assertThat(record(job,resource,"UNKNOWN",UUID.randomUUID().toString()).acknowledged()).isTrue();assertThat(record(job,resource,"UNKNOWN",UUID.randomUUID().toString()).acknowledged()).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='NOTIFICATION_DELIVERY' AND resource_id=?",Long.class,job)).isEqualTo(1);assertThat(record(job,resource,"SENT",UUID.randomUUID().toString()).acknowledged()).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='NOTIFICATION_DELIVERY' AND resource_id=?",Long.class,job)).isEqualTo(2);assertThatThrownBy(()->record(job,resource,"UNKNOWN",UUID.randomUUID().toString())).isInstanceOf(Problem.Failure.class).hasMessage("INVALID_TRANSITION");UUID other=UUID.randomUUID();jdbc.update("INSERT INTO experience.lead(id,created_by,updated_by,type,name,email,subject,message,status,source) VALUES (?, 'notification-test','notification-test','CONTACT','Synthetic','synthetic@example.invalid','Second notification resource','fixture','NEW','WEB')",other);assertThatThrownBy(()->record(job,other,"FAILED",UUID.randomUUID().toString())).isInstanceOf(Problem.Failure.class).hasMessage("NOTIFICATION_RULE_VIOLATION");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='NOTIFICATION_DELIVERY' AND resource_id=?",Long.class,job)).isEqualTo(2);}

    @Test void invalidResourceAndWrongExactScopeAreDeniedBeforeWrite(){UUID job=UUID.randomUUID(),unknown=UUID.randomUUID();assertThatThrownBy(()->record(job,unknown,"FAILED",UUID.randomUUID().toString())).isInstanceOf(Problem.Failure.class).hasMessage("NOT_FOUND");var other=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-122")).findFirst().orElseThrow();var wrong=new PrivateWorkload.Proof(other.client(),"synthetic-integration",other,null);assertThatThrownBy(()->service.record(wrong,delivery(job,resource,"FAILED"),UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class).hasMessage("ACTOR_TRUST_REJECTED");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='NOTIFICATION_DELIVERY' AND resource_id=?",Long.class,job)).isZero();}

    @Test void requestKeyReplayAndConcurrentBusinessKeyRaceCreateOneHistoryRow()throws Exception{UUID job=UUID.randomUUID();String key=UUID.randomUUID().toString();var first=record(job,resource,"FAILED",key);assertThat(record(job,resource,"FAILED",key)).isEqualTo(first);assertThatThrownBy(()->service.record(proof,new NotificationValues.Delivery(job,resource,"SUPPRESSED",null),key,UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class).hasMessage("IDEMPOTENCY_HASH_MISMATCH");UUID racing=UUID.randomUUID();var pool=Executors.newFixedThreadPool(8);var gate=new CountDownLatch(1);try{var calls=new ArrayList<Future<?>>();for(int i=0;i<8;i++)calls.add(pool.submit(()->{gate.await();record(racing,resource,"UNKNOWN",UUID.randomUUID().toString());return null;}));gate.countDown();for(var call:calls)call.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='NOTIFICATION_DELIVERY' AND resource_id=?",Long.class,racing)).isEqualTo(1);}

    @Test void auditFailureRollsBackOutcomeAndCanBeRetried(){UUID job=UUID.randomUUID();var metrics=new SimpleMeterRegistry();var manager=new DataSourceTransactionManager(jdbc.getDataSource());AuditWriter writer=mock(AuditWriter.class);doThrow(new IllegalStateException("synthetic audit failure")).when(writer).append(anyString(),any(),any(),any(),any(),any(),any(),any(),any(),any());var failed=new NotificationOutcomeService(jdbc,new PlatformStore(jdbc,manager,Clock.systemUTC(),metrics),writer,metrics);String key=UUID.randomUUID().toString();assertThatThrownBy(()->failed.record(proof,delivery(job,resource,"FAILED"),key,UUID.randomUUID())).isInstanceOf(IllegalStateException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='NOTIFICATION_DELIVERY' AND resource_id=?",Long.class,job)).isZero();}
}
